import { createHash } from "node:crypto";

// Generated by scripts/embed-dockerfile.mjs from runtime/Dockerfile. Do not edit by hand.
export const DOCKERFILE = [
  "# Sandbox runtime for the Paseo Sandbox plugin: one ordinary Paseo daemon plus the agent CLIs it",
  "# can launch. The plugin builds this file as-is; nothing else is copied in, so any builder that",
  "# understands a Dockerfile can build it, and each instruction maps onto another sandbox format.",
  "#",
  "# Runtime contract (what any sandbox format must provide):",
  "#   - Paseo daemon ${PASEO_VERSION} started as the unprivileged user `paseo` (uid 1000), which also",
  "#     runs every launched agent, terminal and git command",
  "#   - PASEO_PASSWORD from the environment authenticates every daemon client",
  "#   - /home/paseo is the only persistent path: daemon identity, agent logins, project checkouts",
  "#   - claude, codex and opencode on PATH; credentials arrive only through the environment",
  "#   - git reads GITHUB_TOKEN for github.com over https",
  "#   - outbound network to the Paseo relay; no inbound port is needed",
  "ARG PASEO_VERSION=0.13.0",
  "FROM ghcr.io/getpaseo/paseo:${PASEO_VERSION}@sha256:9832cb6bcc904bb7fd6c0b22f1880cde38b592a26ecd38ba66c7fcc76fa0d43e",
  "",
  "# The base entrypoint needs root for first-run volume setup and then drops to `paseo`.",
  "USER root",
  "# The base image points HOME and XDG_* at /home/paseo. Installing from there leaves root-owned",
  "# state that a fresh /home/paseo volume inherits, and the agents then cannot write their own logs.",
  "RUN set -eux; \\",
  "    export HOME=/root XDG_CONFIG_HOME=/root/.config XDG_DATA_HOME=/root/.local/share \\",
  "      XDG_STATE_HOME=/root/.local/state XDG_CACHE_HOME=/root/.cache; \\",
  "    npm install --global --no-audit --no-fund --omit=dev \\",
  "      @anthropic-ai/claude-code@2.1.310 \\",
  "      @openai/codex@0.164.0 \\",
  "      opencode-ai@1.19.4; \\",
  "    npm cache clean --force; \\",
  "    rm -rf /root/.cache /root/.local /root/.npm; \\",
  "    git config --system 'credential.https://github.com.helper' \\",
  "      '!f() { test \"$1\" = get && test -n \"$GITHUB_TOKEN\" && echo username=x-access-token && echo \"password=$GITHUB_TOKEN\"; }; f'; \\",
  "    test -z \"$(find /home/paseo -user root -print -quit)\"",
  "",
  "# The sandbox is reached through the relay, so the bundled web UI has no audience.",
  "ENV PASEO_WEB_UI_ENABLED=false",
  "",
].join("\n");

/** The tag changes with the Dockerfile, so an upgraded plugin builds its own image once. */
export const IMAGE_TAG = `paseo-sandbox:${createHash("sha256").update(DOCKERFILE).digest("hex").slice(0, 12)}`;
